const response = $input.first().json;
const products = response.products || [];

const seenIds = new Set();
const results = [];

for (const product of products) {
  const issues = [];

  // Check missing fields
  if (!product.id) issues.push("Missing product ID");
  if (!product.title) issues.push("Missing title");
  if (product.price === undefined || product.price === null) {
    issues.push("Missing price");
  }

  // Check invalid values
  if (typeof product.price !== "number" || product.price <= 0) {
    issues.push("Invalid price");
  }

  if (typeof product.stock !== "number" || product.stock < 0) {
    issues.push("Invalid stock");
  }

  // Check duplicate IDs
  if (seenIds.has(product.id)) {
    issues.push("Duplicate product ID");
  }
  seenIds.add(product.id);

  results.push({
    json: {
      product_id: product.id ?? null,
      title: product.title ?? null,
      price: product.price ?? null,
      stock: product.stock ?? null,
      category: product.category ?? null,
      quality_status: issues.length === 0 ? "PASS" : "FAIL",
      issue_count: issues.length,
      issues: issues
    }
  });
}

const failed = results.filter(item =>
  item.json.quality_status === "FAIL"
).length;

return [
  {
    json: {
      total_records: results.length,
      passed_records: results.length - failed,
      failed_records: failed,
      quality_score: results.length
        ? Number(((results.length - failed) / results.length * 100).toFixed(2))
        : 0,
      validation_results: results.map(item => item.json)
    }
  }
];
